// MotivationalTip.kt
// This file defines a Room Entity for storing motivational tips.
// Each entry in this table represents one motivational tip that can be displayed in the app.

package com.fit2081.fit2081assignment1.data

import androidx.room.Entity
import androidx.room.PrimaryKey

// Annotates this class as a Room Entity and sets the table name as "motivational_tips"
@Entity(tableName = "motivational_tips")
data class MotivationalTip(
    // The primary key for the table. It is auto-generated by Room.
    @PrimaryKey(autoGenerate = true) val id: Int = 0,

    // The motivational tip text to be stored in the table.
    val tip: String
)